package org.apache.commons.codec.binary;

import org.junit.Test;
import static org.junit.Assert.*;
import static org.evosuite.runtime.EvoAssertions.*;
import java.nio.ByteBuffer;
import java.nio.CharBuffer;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringUtils_ESTest_test18 extends StringUtils_ESTest_scaffolding {

    /**
     * Decoding four zero bytes as UTF-16 produces two NUL characters: UTF-16 uses
     * two bytes per character, so a 4-byte input yields a 2-character String, each
     * character being the null character (U+0000).
     */
    @Test(timeout = 4000)
    public void newStringUtf16DecodesZeroBytesToTwoNullCharacters() throws Throwable {
        byte[] fourZeroBytes = new byte[4];

        String decoded = StringUtils.newStringUtf16(fourZeroBytes);

        // A String containing exactly two null characters ("��").
        String expectedTwoNullChars = new String(new char[2]);
        assertEquals(expectedTwoNullChars, decoded);
    }
}
